import{_ as a,o,c as i,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"2. Capítulo II: Marco Referencial (Ejemplo Real)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/2_Capitulo_II_Marco_Referencial.md","filePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/2_Capitulo_II_Marco_Referencial.md"}'),t={name:"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/2_Capitulo_II_Marco_Referencial.md"};function r(l,e,s,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_2-capitulo-ii-marco-referencial-ejemplo-real" tabindex="-1">2. Capítulo II: Marco Referencial (Ejemplo Real) <a class="header-anchor" href="#_2-capitulo-ii-marco-referencial-ejemplo-real" aria-label="Permalink to &quot;2. Capítulo II: Marco Referencial (Ejemplo Real)&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Instrucciones de Uso:</strong> Este capítulo es el fundamento académico de tu proyecto. Aquí demuestras que investigaste trabajos previos, que conoces la teoría de lo que vas a hacer y que tu proyecto se enmarca dentro de la ley venezolana. Toda definición debe llevar cita de autor (Normas APA).</p></div><hr><h2 id="capitulo-ii" tabindex="-1">CAPÍTULO II <a class="header-anchor" href="#capitulo-ii" aria-label="Permalink to &quot;CAPÍTULO II&quot;">​</a></h2><h2 id="marco-referencial-de-la-investigacion" tabindex="-1">MARCO REFERENCIAL DE LA INVESTIGACIÓN <a class="header-anchor" href="#marco-referencial-de-la-investigacion" aria-label="Permalink to &quot;MARCO REFERENCIAL DE LA INVESTIGACIÓN&quot;">​</a></h2><h3 id="_2-1-antecedentes-de-la-investigacion" tabindex="-1">2.1 Antecedentes de la Investigación <a class="header-anchor" href="#_2-1-antecedentes-de-la-investigacion" aria-label="Permalink to &quot;2.1 Antecedentes de la Investigación&quot;">​</a></h3><p><em>Los antecedentes son proyectos pasados (de tu universidad u otras) que se parecen al tuyo. Debes citar al menos 3.</em></p><p>Para fundamentar la presente investigación, se revisaron trabajos de grado previos relacionados con la línea de Informática Aplicada. Al respecto, <strong>[Pérez y Rojas (2025)]</strong> en su proyecto titulado <em>&quot;Soporte Técnico a la Unidad Educativa Las Américas&quot;</em> realizado en la UPTT, concluyeron que el mantenimiento preventivo constante reduce en un 60% la falla catastrófica de los discos duros mecánicos. Este antecedente aporta a la presente investigación <strong>[la justificación de que el mantenimiento preventivo es la estrategia más viable económicamente para las escuelas públicas]</strong>.</p><h3 id="_2-2-bases-teoricas" tabindex="-1">2.2 Bases Teóricas <a class="header-anchor" href="#_2-2-bases-teoricas" aria-label="Permalink to &quot;2.2 Bases Teóricas&quot;">​</a></h3><p><em>Aquí defines como si fueras un diccionario todos los conceptos técnicos que usarás en tu proyecto. Todo debe ir citado.</em></p><p>Para comprender la magnitud técnica del proyecto, se definen los siguientes conceptos fundamentales:</p><ul><li><strong>Soporte Técnico:</strong> Según <strong>[García (2022)]</strong>, es un rango de servicios por medio del cual se proporciona asistencia a los usuarios al tener algún problema al utilizar un producto o servicio informático. En este proyecto, aplica para la atención directa a los usuarios del laboratorio.</li><li><strong>Mantenimiento Preventivo:</strong> Se refiere a <strong>[la revisión técnica programada a los equipos de computación, que incluye limpieza de hardware y actualización de software, con el fin de evitar fallas futuras (López, 2023)]</strong>.</li><li><strong>Software Libre:</strong> De acuerdo con la <strong>[Free Software Foundation (2020)]</strong>, es el software que respeta la libertad de los usuarios y la comunidad, permitiendo ejecutar, copiar, distribuir, estudiar, modificar y mejorar el software.</li></ul><h3 id="_2-3-bases-legales" tabindex="-1">2.3 Bases Legales <a class="header-anchor" href="#_2-3-bases-legales" aria-label="Permalink to &quot;2.3 Bases Legales&quot;">​</a></h3><p><em>En Venezuela, todo proyecto socio-tecnológico del Estado debe cumplir con la ley. Nunca puede faltar la Constitución, el Plan de la Patria y la Ley de Infogobierno.</em></p><p>El desarrollo de este Proyecto Sociotecnológico se sustenta en el siguiente marco jurídico nacional:</p><p><strong>Constitución de la República Bolivariana de Venezuela (1999)</strong></p><ul><li><strong>Artículo 110:</strong> <em>“El Estado reconocerá el interés público de la ciencia, la tecnología, el conocimiento, la innovación y sus aplicaciones y los servicios de información necesarios por ser instrumentos fundamentales para el desarrollo económico, social y político del país...”</em></li><li><em>Relación con el proyecto:</em> Este artículo justifica la intervención de estudiantes universitarios en la comunidad para llevar servicios de información (el laboratorio) que fomenten el desarrollo educativo del sector.</li></ul><p><strong>Ley de Infogobierno (2013)</strong></p><ul><li><strong>Artículo 34:</strong> <em>“El desarrollo, adquisición, implementación y uso de las tecnologías de información por parte del Poder Público, debe realizarse utilizando software libre y estándares abiertos...”</em></li><li><em>Relación con el proyecto:</em> Esta ley obliga y justifica técnicamente que la instalación de sistemas operativos en los equipos de la escuela (institución del Estado) se realice utilizando distribuciones de GNU/Linux, garantizando la soberanía tecnológica.</li></ul><p><strong>Plan de la Patria (2019-2025)</strong></p><ul><li><strong>Objetivo Histórico 1:</strong> <em>Defender, expandir y consolidar el bien más preciado que hemos reconquistado después de 200 años: la independencia nacional.</em></li><li><em>Relación con el proyecto:</em> Al formar a los usuarios en tecnologías libres e independizarlos del software privativo, el proyecto contribuye directamente a la independencia tecnológica de la nación.</li></ul>',21)])])}const g=a(t,[["render",r]]);export{m as __pageData,g as default};
